def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.35))

    prev_bids = []
    rich_pressure = 0
    desperate_opp = 0
    for oid, opp in alive:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if float(bid) >= 110:
                rich_pressure += 1
        if opp.get('no_water_days', 0) >= 2 or opp.get('hp', 10) <= 2:
            desperate_opp += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    low_supply = supply <= 17
    high_supply = supply >= 22

    critical = (no_water >= 2) or (hp <= 2)
    urgent = (no_water >= 1 and hp <= 4) or (hp <= 3)

    if critical:
        bid = max(118.0, highest_prev + 4.0, DAILY_SALARY * 1.55)
        return float(min(budget, bid))

    if urgent:
        if low_supply:
            bid = max(102.0, highest_prev + 2.5, avg_prev + 8.0)
        else:
            bid = max(88.0, avg_prev + 5.0)
        return float(min(budget, bid))

    if high_supply and rich_pressure >= 2:
        return float(min(budget, DAILY_SALARY * 0.22))

    if low_supply:
        if rich_pressure >= 2:
            bid = max(74.0, avg_prev * 0.72)
        else:
            bid = max(79.0, highest_prev + 1.5, avg_prev + 4.0)
    else:
        if desperate_opp >= 2:
            bid = max(42.0, avg_prev * 0.55)
        elif highest_prev >= 120:
            bid = 36.0
        elif highest_prev >= 90:
            bid = 48.0
        else:
            bid = max(44.0, avg_prev * 0.7, DAILY_SALARY * 0.58)

    if day >= 8 and hp >= 5 and no_water == 0:
        bid *= 0.9

    return float(min(budget, max(0.0, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # Strategy 1: If I'm the only one left, bid conservatively
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Strategy 2: Adjust bid based on opponents' previous bids and my HP
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        # If opponents are bidding very high (e.g., >= 85% of my daily salary)
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 3: # If my HP is stable, consider letting them overbid and conserve budget
                return min(my_status['budget'], DAILY_SALARY * 0.3)
            else: # If my HP is critical (<=3), I need water, bid aggressively
                return min(my_status['budget'], DAILY_SALARY * 0.95)
        else: # Opponents are not bidding excessively high
            # Bid slightly above the highest previous bid, but at least 50% of salary
            # This aims to win without overpaying too much
            return min(my_status['budget'], max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5))
    else:
        # Strategy 3: No previous bids or initial days, bid based on my HP
        if my_status['hp'] <= 2: # Critical HP (can survive 2 more days without water)
            return min(my_status['budget'], DAILY_SALARY * 0.9)
        else: # Stable HP
            return min(my_status['budget'], DAILY_SALARY * 0.55)
